<?php
/**
 * Front-end assets.
 *
 * - dist/main.css is LTR; dist/main-rtl.css is generated by RTLCSS and replaces it in RTL.
 * - Source CSS uses logical properties, so RTL output differs very little from LTR.
 * - Fonts are self-hosted (no external requests): Inter for Latin, IBM Plex Sans Arabic for Arabic.
 *
 * @package SM_Marketplace
 */

defined( 'ABSPATH' ) || exit;

function sm_theme_asset_version( $relative ) {
	$path = SM_THEME_DIR . '/' . $relative;
	return file_exists( $path ) ? SM_THEME_VERSION . '.' . filemtime( $path ) : SM_THEME_VERSION;
}

function sm_theme_enqueue_assets() {
	wp_enqueue_style( 'sm-main', SM_THEME_URI . '/dist/main.css', array(), sm_theme_asset_version( 'dist/main.css' ) );
	wp_style_add_data( 'sm-main', 'rtl', 'replace' );
	wp_style_add_data( 'sm-main', 'suffix', '' );

	wp_enqueue_script( 'sm-main', SM_THEME_URI . '/assets/js/main.js', array(), sm_theme_asset_version( 'assets/js/main.js' ), array( 'in_footer' => true, 'strategy' => 'defer' ) );
	wp_enqueue_script( 'sm-motion', SM_THEME_URI . '/assets/js/motion.js', array(), sm_theme_asset_version( 'assets/js/motion.js' ), array( 'in_footer' => true, 'strategy' => 'defer' ) );
	if ( sm_theme_is_home() ) {
		// The 3D beam of the hero: loads Three.js itself, after the page, on desktops only.
		wp_enqueue_script( 'sm-hero-3d', SM_THEME_URI . '/assets/js/hero-3d.js', array(), sm_theme_asset_version( 'assets/js/hero-3d.js' ), array( 'in_footer' => true, 'strategy' => 'defer' ) );
	}
	wp_localize_script(
		'sm-main',
		'smTheme',
		array(
			'dir'  => sm_theme_dir(),
			'lang' => sm_theme_current_language(),
			'i18n' => array(
				'openMenu'  => __( 'Open menu', 'sm-marketplace' ),
				'closeMenu' => __( 'Close menu', 'sm-marketplace' ),
				'show'      => __( 'Show', 'sm-marketplace' ),
				'hide'      => __( 'Hide', 'sm-marketplace' ),
				'saved'     => __( 'Saved', 'sm-marketplace' ),
				'removed'   => __( 'Removed from saved listings', 'sm-marketplace' ),
				'uploaded'  => __( 'Uploaded', 'sm-marketplace' ),
				/* translators: %s: file name. */
				'removeFile' => __( 'Remove %s', 'sm-marketplace' ),
				'addMore'   => __( 'Add other files', 'sm-marketplace' ),
				'tooMany'   => __( 'Too many files: the extra ones were not added.', 'sm-marketplace' ),
				'toDelete'  => __( 'Will be deleted when you save', 'sm-marketplace' ),
				'toReplace' => __( 'Will be replaced when you save', 'sm-marketplace' ),
				'undo'      => __( 'Undo', 'sm-marketplace' ),
				'delete'    => __( 'Delete', 'sm-marketplace' ),
				'close'     => __( 'Close', 'sm-marketplace' ),
				'prev'      => __( 'Previous photo', 'sm-marketplace' ),
				'next'      => __( 'Next photo', 'sm-marketplace' ),
				'original'  => __( 'Original size', 'sm-marketplace' ),
			),
		)
	);

	if ( ! is_admin() ) {
		wp_dequeue_style( 'wp-block-library' );
		wp_dequeue_style( 'global-styles' );
		wp_dequeue_style( 'classic-theme-styles' );
	}
}
add_action( 'wp_enqueue_scripts', 'sm_theme_enqueue_assets', 20 );

/** Weight calculator live refresh (loaded by the weight-calculator component). */
function sm_theme_enqueue_weight() {
	wp_enqueue_script( 'sm-weight', SM_THEME_URI . '/assets/js/weight.js', array(), sm_theme_asset_version( 'assets/js/weight.js' ), array( 'in_footer' => true, 'strategy' => 'defer' ) );
}

/**
 * Location map: self-hosted Leaflet + map.js, loaded only on pages that show a
 * map (called by the location-map component). Map data (wilaya centres, tile
 * server, bounds) comes from sm-core through the data contract.
 */
function sm_theme_enqueue_map() {
	static $done = false;
	if ( $done ) {
		return;
	}
	$done = true;
	$base = SM_THEME_URI . '/assets/vendor/leaflet';
	wp_enqueue_style( 'leaflet', $base . '/leaflet.css', array(), '1.9.4' );
	wp_enqueue_script( 'leaflet', $base . '/leaflet.js', array(), '1.9.4', array( 'in_footer' => true ) );
	wp_enqueue_script( 'sm-map', SM_THEME_URI . '/assets/js/map.js', array( 'leaflet' ), sm_theme_asset_version( 'assets/js/map.js' ), array( 'in_footer' => true ) );

	$map = (array) sm_theme_data( 'map' );
	wp_localize_script(
		'sm-map',
		'smMap',
		array(
			'imagePath'   => $base . '/images/',
			'tiles'       => $map['tiles'] ?? 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
			'attribution' => $map['attribution'] ?? '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
			'maxZoom'     => (int) ( $map['max_zoom'] ?? 19 ),
			'bounds'      => $map['bounds'] ?? null,
			'country'     => $map['country'] ?? null,
			'centres'     => (object) sm_theme_data( 'wilaya_centres' ),
			'i18n'        => array(
				'marker'        => __( 'Company position. Drag it, or use the arrow keys.', 'sm-marketplace' ),
				'none'          => __( 'No position yet.', 'sm-marketplace' ),
				'drag'          => __( 'Drag the marker to your exact address, or click the map.', 'sm-marketplace' ),
				'set'           => __( 'Position placed:', 'sm-marketplace' ),
				'located'       => __( 'Current location found:', 'sm-marketplace' ),
				/* translators: %d: accuracy in metres. */
				'approx'        => __( 'Approximate (about %d m): drag the marker to correct it.', 'sm-marketplace' ),
				'locating'      => __( 'Looking for your location…', 'sm-marketplace' ),
				'denied'        => __( 'Location access was refused. Allow it in your browser, or place the marker by hand.', 'sm-marketplace' ),
				'unavailable'   => __( 'Your location could not be found. Place the marker by hand.', 'sm-marketplace' ),
				'timeout'       => __( 'Finding your location took too long. Try again or place the marker by hand.', 'sm-marketplace' ),
				'insecure'      => __( 'Your browser only shares your location on a secure (https) site. Place the marker by hand.', 'sm-marketplace' ),
				'outside'       => __( 'This position is outside Algeria. Place the marker on your address.', 'sm-marketplace' ),
				'wilayaChanged' => __( 'Wilaya changed: place the marker again on your address.', 'sm-marketplace' ),
				'removed'       => __( 'Position removed. It will be deleted when you save.', 'sm-marketplace' ),
			),
		)
	);
}

/**
 * WordPress normally builds the RTL file name as main-rtl.css: make sure that file is used.
 */
function sm_theme_rtl_style_src( $src, $handle ) {
	if ( 'sm-main' === $handle && 'rtl' === sm_theme_dir() ) {
		$src = str_replace( '/dist/main.css', '/dist/main-rtl.css', $src );
	}
	return $src;
}
add_filter( 'style_loader_src', 'sm_theme_rtl_style_src', 10, 2 );

/** Preload the fonts the first screen needs for the current language. */
function sm_theme_preload_fonts() {
	$fonts = 'rtl' === sm_theme_dir()
		? array( 'plex-arabic-400', 'plex-arabic-600' )
		: array( 'inter-400', 'inter-600' );
	foreach ( $fonts as $font ) {
		printf( '<link rel="preload" href="%s" as="font" type="font/woff2" crossorigin>' . "\n", esc_url( SM_THEME_URI . '/assets/fonts/' . $font . '.woff2' ) );
	}
}
add_action( 'wp_head', 'sm_theme_preload_fonts', 1 );

/** Inline the SVG icon sprite once, right after <body>. */
function sm_theme_icon_sprite() {
	$sprite = SM_THEME_DIR . '/assets/icons/sprite.svg';
	if ( file_exists( $sprite ) ) {
		// The sprite is a static file shipped with the theme.
		echo file_get_contents( $sprite ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped, WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	}
}
add_action( 'wp_body_open', 'sm_theme_icon_sprite', 1 );

/**
 * Page transitions are a nicety: a cross-document transition the browser skips
 * (fast clicks, form redirects) must not surface as an error. Printed in <head>
 * because "pagereveal" fires before deferred scripts run.
 */
function sm_theme_quiet_transitions() {
	echo "<script>(function(){function q(e){var v=e.viewTransition;if(!v){return;}[v.ready,v.finished,v.updateCallbackDone].forEach(function(p){if(p&&p.catch){p.catch(function(){});}});}addEventListener('pageswap',q);addEventListener('pagereveal',q);addEventListener('unhandledrejection',function(e){var r=e.reason;if(r&&/Transition/.test(String(r.message||''))){e.preventDefault();}});}());</script>\n"; // phpcs:ignore WordPress.Security.EscapeOutput
}
add_action( 'wp_head', 'sm_theme_quiet_transitions', 0 );
